@ Hello World in ARM Assembly\n@ For Linux on ARM\n\n.global _start\n\n.section .data\nmsg:\n    .ascii "Hello, World!\n"\n    msg_len = . - msg\n\n.section .text\n_start:\n    @ write syscall\n    mov r0, #1          @ stdout\n    ldr r1, =msg        @ message address\n    ldr r2, =msg_len    @ message length\n    mov r7, #4          @ syscall number (write)\n    svc #0              @ make syscall\n\n    @ exit syscall\n    mov r0, #0          @ exit code\n    mov r7, #1          @ syscall number (exit)\n    svc #0              @ make syscall